    95→    const selectedDef = CHARACTERS.find(c => c.id === this.selectedId) ?? CHARACTERS[0];
    96→
    97→    // ── 배경: 선택된 캐릭터 일러스트 ───────────────────────────────────
    98→    this.bgImage = this.add.image(200, 300, selectedDef.illustKey);
    99→    this.bgImage.setDisplaySize(400, 600);
   100→
   101→    // ── 헤더 (고정) ─────────────────────────────────────────────────────
   102→    this.add.text(200, 40, '캐릭터 선택', {
   103→      fontSize: '26px',
   104→      color: '#ffffff',
   105→      fontStyle: 'bold',
   106→      stroke: '#000',
   107→      strokeThickness: 4,
   108→    }).setOrigin(0.5);
   109→
   110→    this.headerNameText = this.add.text(200, 80, `현재: ${selectedDef.name}`, {
   111→      fontSize: '16px',
   112→      color: selectedDef.gradeColor,
   113→      stroke: '#000',
   114→      strokeThickness: 3,
   115→    }).setOrigin(0.5);
   116→
   117→    this.add.text(200, 108, '수집한 캐릭터를 선택하세요', {
   118→      fontSize: '13px',
   119→      color: '#888888',
   120→    }).setOrigin(0.5);
   121→
   122→    // ── 스크롤 가능한 카드 컨테이너 ─────────────────────────────────────
   123→    this.cardsContainer = this.add.container(0, 0);
   124→
   125→    CHARACTERS.forEach((char, index) => {
   126→      const col = index % COLS;
   127→      const row = Math.floor(index / COLS);
   128→      const x = GRID_LEFT + col * (CARD_W + GAP_X) + CARD_W / 2;
   129→      const y = GRID_TOP + row * (CARD_H + GAP_Y) + CARD_H / 2;
   130→      this.createCharacterCard(char, x, y);
   131→    });
   132→
   133→    // 스크롤 최대 범위 계산
   134→    const totalRows = Math.ceil(CHARACTERS.length / COLS);
   135→    const contentBottom = GRID_TOP + (totalRows - 1) * (CARD_H + GAP_Y) + CARD_H + 10;
   136→    this.maxScrollOffset = Math.max(0, contentBottom - SCROLL_BOTTOM);
   137→
   138→    // 카드 영역 마스크 (스크롤 영역 밖 숨김)
   139→    const maskGfx = this.make.graphics({ x: 0, y: 0 });
   140→    maskGfx.fillStyle(0xffffff);
   141→    maskGfx.fillRect(0, SCROLL_TOP, 400, SCROLL_BOTTOM - SCROLL_TOP);
   142→    this.cardsContainer.setMask(maskGfx.createGeometryMask());
   143→
   144→    // ── 드래그 스크롤 입력 ───────────────────────────────────────────────
   145→    this.input.on('pointerdown', (p: Phaser.Input.Pointer) => {
   146→      this.hasPointerDownInScene = true;
   147→      if (this.detailPanel) return; // 상세 패널 열려있으면 스크롤 무시
   148→      if (p.y < SCROLL_TOP || p.y > SCROLL_BOTTOM) return;
   149→      this.pointerDownY = p.y;
   150→      this.pointerDownScrollY = this.scrollOffset;
   151→      this.hasDragged = false;
   152→    });
   153→
   154→    this.input.on('pointermove', (p: Phaser.Input.Pointer) => {
   155→      if (this.detailPanel) return; // 상세 패널 열려있으면 스크롤 무시
   156→      if (!p.isDown) return;
   157→      const dy = this.pointerDownY - p.y;
   158→      if (Math.abs(dy) > 5) {
   159→        this.hasDragged = true;
   160→        this.scrollOffset = Phaser.Math.Clamp(
   161→          this.pointerDownScrollY + dy,
   162→          0,
   163→          this.maxScrollOffset,
   164→        );
   165→        this.cardsContainer.setY(-this.scrollOffset);
   166→      }
   167→    });
   168→
   169→    this.input.on('pointerup', () => {
   170→      if (this.detailPanel) return; // 상세 패널 열려있으면 hasDragged 초기화 무시
   171→      // card pointerup 이벤트가 먼저 발생하므로 다음 프레임에 초기화
   172→      this.time.delayedCall(0, () => {
   173→        this.hasDragged = false;
   174→        this.hasPointerDownInScene = false;
   175→      });
   176→    });
   177→
   178→    // 마우스 휠
   179→    this.input.on(
   180→      'wheel',
   181→      (_p: Phaser.Input.Pointer, _go: unknown[], _dx: number, deltaY: number) => {
   182→        if (this.detailPanel) return; // 상세 패널 열려있으면 휠 스크롤 무시
   183→        this.scrollOffset = Phaser.Math.Clamp(
   184→          this.scrollOffset + deltaY * 0.5,
   185→          0,
   186→          this.maxScrollOffset,
   187→        );
   188→        this.cardsContainer.setY(-this.scrollOffset);
   189→      },
   190→    );
   191→
   192→    // ── 고정 UI ─────────────────────────────────────────────────────────
   193→    this.createBackButton();
   194→  }
