   196→  private createCharacterCard(char: CharacterDef, x: number, y: number) {
   197→    const isOwned = this.ownedIds.includes(char.id);
   198→    const isSelected = this.selectedId === char.id;
   199→    const gradeColorInt = parseInt(char.gradeColor.replace('#', ''), 16);
   200→
   201→    // 카드 배경
   202→    const cardBg = this.add.rectangle(x, y, CARD_W, CARD_H, 0x222222);
   203→    cardBg.setStrokeStyle(2, isOwned ? gradeColorInt : 0x444444);
   204→    this.cardsContainer.add(cardBg);
   205→
   206→    // 선택 하이라이트
   207→    const highlight = this.add.rectangle(x, y, CARD_W, CARD_H, 0, 0);
   208→    highlight.setStrokeStyle(3, 0xffffff);
   209→    highlight.setVisible(isSelected);
   210→    this.cardHighlights.set(char.id, highlight);
   211→    this.cardsContainer.add(highlight);
   212→
   213→    // 캐릭터 이미지
   214→    const img = this.add.image(x, y - 12, char.imageKey);
   215→    img.setDisplaySize(58, 85);
   216→    this.cardsContainer.add(img);
   217→
   218→    if (!isOwned) {
   219→      img.setTint(0x000000);
   220→      img.setAlpha(0.6);
   221→      const lock = this.add.text(x, y - 12, '🔒', { fontSize: '22px' }).setOrigin(0.5);
   222→      this.cardsContainer.add(lock);
   223→    }
   224→
   225→    // 등급 배지
   226→    const badge = this.add.text(x + CARD_W / 2 - 2, y - CARD_H / 2 + 2, char.grade, {
   227→      fontSize: '9px',
   228→      color: char.gradeColor,
   229→      fontStyle: 'bold',
   230→      backgroundColor: '#000000cc',
   231→      padding: { x: 3, y: 1 },
   232→    }).setOrigin(1, 0);
   233→    this.cardsContainer.add(badge);
   234→
   235→    // 각성 코어 (등급외 제외, 보유 캐릭터만)
   236→    if (isOwned && char.grade !== '등급외') {
   237→      const dupCount     = getDuplicateCount(char.id);
   238→      const awakeLevel   = getAwakeningLevel(char.grade, dupCount);
   239→      const gradeColor   = parseInt(char.gradeColor.replace('#', ''), 16);
   240→      const coreY        = y + CARD_H / 2 - 28;
   241→      const coreGap      = 10;
   242→      const gfx          = this.add.graphics();
   243→
   244→      for (let i = 0; i < 5; i++) {
   245→        const cx = x + (i - 2) * coreGap;
   246→        if (i < awakeLevel) {
   247→          // 충전된 코어: 외곽 글로우 + 내부 밝은 원
   248→          gfx.fillStyle(gradeColor, 0.25);
   249→          gfx.fillCircle(cx, coreY, 5.5);
   250→          gfx.fillStyle(gradeColor, 1);
   251→          gfx.fillCircle(cx, coreY, 3.5);
   252→          gfx.fillStyle(0xffffff, 0.55);
   253→          gfx.fillCircle(cx - 1, coreY - 1, 1.2);
   254→        } else {
   255→          // 빈 코어: 어두운 원 + 얇은 테두리
   256→          gfx.fillStyle(0x111111, 1);
   257→          gfx.fillCircle(cx, coreY, 3.5);
   258→          gfx.lineStyle(1, gradeColor, 0.35);
   259→          gfx.strokeCircle(cx, coreY, 3.5);
   260→        }
   261→      }
   262→      this.cardsContainer.add(gfx);
   263→    }
   264→
   265→    // 캐릭터 이름
   266→    const nameText = this.add.text(x, y + CARD_H / 2 - 16, char.name, {
   267→      fontSize: '12px',
   268→      color: isOwned ? '#ffffff' : '#555555',
   269→      fontStyle: 'bold',
   270→    }).setOrigin(0.5);
   271→    this.cardsContainer.add(nameText);
   272→
   273→    // 모든 카드 클릭 가능 (탭 → 상세 패널 열기)
   274→    cardBg.setInteractive({ useHandCursor: isOwned });
   275→
   276→    if (isOwned) {
   277→      cardBg.on('pointerover', () => {
   278→        if (this.selectedId !== char.id) cardBg.setFillStyle(0x333333);
   279→      });
   280→      cardBg.on('pointerout', () => {
   281→        if (this.selectedId !== char.id) cardBg.setFillStyle(0x222222);
   282→      });
   283→    }
   284→    // pointerup으로 상세 패널 열기 (드래그 스크롤과 구분, 이전 씬 bleed-through 방지)
   285→    cardBg.on('pointerup', () => {
   286→      if (!this.hasDragged && this.hasPointerDownInScene) this.showCharacterDetail(char.id);
   287→    });
   288→  }
