   405→      const lockBg = this.add.rectangle(292, BTN_Y, BTN_W, BTN_H, 0x1a1a1a)
   406→        .setStrokeStyle(1.5, 0x444444);
   407→      const lockLabel = this.add.text(292, BTN_Y, '🔒  미보유', {
   408→        fontSize: '14px', color: '#555555',
