   429→      illust.setInteractive({ useHandCursor: true });
   430→      illust.on('pointerup', startVideo);
   431→
   432→      // 비디오 탭 또는 재생 완료 → 일러스트로 복귀
   433→      const stopVideo = () => {
   434→        videoObj!.stop();
   435→        videoObj!.setVisible(false);
   436→        illust.setVisible(true);
   437→      };
   438→      videoObj.setInteractive({ useHandCursor: true });
   439→      videoObj.on('pointerup', stopVideo);
   440→      videoObj.on('complete', stopVideo);
   441→    }
   442→  }
