   476→  private showInfoPanel(def: CharacterDef): void {
   477→    this.hideInfoPanel();
   478→
   479→    const gradeColorInt = parseInt(def.gradeColor.replace('#', ''), 16);
   480→    const panel = this.add.container(0, 0).setDepth(400);
   481→    this.infoPanel = panel;
   482→
   483→    // ── 각성 보너스 계산 ──────────────────────────────────────────────
   484→    const dupCount   = getDuplicateCount(def.id);
   485→    const awakeLevel = getAwakeningLevel(def.grade, dupCount);
   486→    const awakeBonusLines: string[] = [];
   487→    if (def.grade !== '등급외') {
   488→      if (awakeLevel >= 1) {
   489→        const spd = def.id === 'maehwa' ? 5 : def.grade === 'UR' ? 15 : def.grade === 'SR' ? 10 : 5;
   490→        awakeBonusLines.push(`★1 각성: 이동속도 +${spd} px/s`);
   491→      }
   492→      if (awakeLevel >= 2) {
   493→        if (def.id === 'maehwa') {
   494→          awakeBonusLines.push('★2 각성: 특수 똥 수집 시 +5점');
   495→        } else {
   496→          const spd = def.grade === 'UR' ? 20 : def.grade === 'SR' ? 15 : 10;
   497→          awakeBonusLines.push(`★2 각성: 이동속도 +${spd} px/s (누적)`);
   498→        }
   499→      }
   500→    }
   501→    const awakeBonusText = awakeBonusLines.join('\n');
   502→
   503→    // 반투명 배경 (클릭 시 닫기)
   504→    const overlay = this.add.rectangle(200, 300, 400, 600, 0x000000, 0.80)
   505→      .setInteractive();
   506→    overlay.on('pointerup', () => this.hideInfoPanel());
   507→    panel.add(overlay);
   508→
   509→    // ── 카드 크기 계산 (텍스트 높이 선측정) ─────────────────────────
   510→    const B_LEFT = 30;
