     1→import Phaser from 'phaser';
     2→import { BaseAbility } from './BaseAbility';
     3→import type { GameSceneAPI } from './types';
     4→import { HACKER_PARAMS } from '../config/abilityParams';
     5→
     6→/**
     7→ * 루트 (SR) — 터미널 삭제
     8→ * 수치: HACKER_PARAMS 참조
     9→ */
    10→export class HackerAbility extends BaseAbility {
    11→  private lastHackerScore = 0;
    12→
    13→  override specialPoopSpeedReduction(_type: 'gold' | 'diamond'): number {
    14→    return HACKER_PARAMS.specialPoopSlowdown;
    15→  }
    16→
    17→  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    18→    if (!api.isClassicMode) return;
    19→    if (score % HACKER_PARAMS.deleteInterval === 0 && score > this.lastHackerScore) {
    20→      this.lastHackerScore = score;
    21→      this.removeRandomPoops(HACKER_PARAMS.deleteCount, api);
    22→    }
    23→  }
    24→
    25→  private removeRandomPoops(count: number, api: GameSceneAPI): void {
    26→    const active = api.poops
    27→      .getChildren()
    28→      .filter(p => (p as Phaser.GameObjects.GameObject).active) as Phaser.Physics.Arcade.Sprite[];
    29→
    30→    active.sort(() => Math.random() - 0.5);
    31→    active.slice(0, count).forEach(p => {
    32→      (p.body as Phaser.Physics.Arcade.Body).setVelocity(0, 0);
    33→      this.playTerminalEffect(p.x, p.y, api);
    34→      p.destroy();
    35→    });
    36→  }
    37→
    38→  /** 초록 테두리 검정 박스 flash → 픽셀 비산 */
    39→  private playTerminalEffect(cx: number, cy: number, api: GameSceneAPI): void {
    40→    const scene = api.scene;
    41→    const BOX_W = 36, BOX_H = 36;
    42→
    43→    const box = scene.add.graphics().setDepth(110);
    44→    box.fillStyle(0x000000, 1);
    45→    box.fillRect(-BOX_W / 2, -BOX_H / 2, BOX_W, BOX_H);
    46→    box.lineStyle(2, 0x00ff41, 1);
    47→    box.strokeRect(-BOX_W / 2, -BOX_H / 2, BOX_W, BOX_H);
    48→    box.setPosition(cx, cy);
    49→
    50→    scene.tweens.add({
    51→      targets: box,
    52→      alpha: 0,
    53→      duration: 180,
    54→      delay: 60,
    55→      onComplete: () => box.destroy(),
    56→    });
    57→
    58→    const PIXEL_COUNT = 10;
    59→    const GREEN = 0x00ff41;
    60→
    61→    for (let i = 0; i < PIXEL_COUNT; i++) {
    62→      const size  = Phaser.Math.Between(4, 9);
    63→      const angle = Phaser.Math.FloatBetween(0, Math.PI * 2);
    64→      const speed = Phaser.Math.FloatBetween(40, 110);
    65→      const tx    = cx + Math.cos(angle) * speed;
    66→      const ty    = cy + Math.sin(angle) * speed;
    67→
    68→      const px = scene.add.graphics().setDepth(111);
    69→      px.fillStyle(GREEN, 1);
    70→      px.fillRect(0, 0, size, size);
    71→      px.setPosition(cx, cy);
    72→
    73→      scene.tweens.add({
    74→        targets: px,
    75→        x: tx,
    76→        y: ty + Phaser.Math.Between(10, 30),
    77→        alpha: 0,
    78→        duration: Phaser.Math.Between(250, 420),
    79→        ease: 'Quad.easeOut',
    80→        onComplete: () => px.destroy(),
    81→      });
    82→    }
    83→  }
    84→}
